// Secure Express application with comprehensive error handling and input validation
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');
const app = express();

// Security Middleware
app.use(helmet()); // Set security headers
app.use(express.json({ limit: '10kb' })); // Limit JSON payload size
app.use(express.urlencoded({ extended: true, limit: '10kb' })); // Limit URL-encoded payload size

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// CORS configuration (adjust for production)
app.use((req, res, next) => {
  res.header('Access-Control-Allow-Origin', process.env.ALLOWED_ORIGIN || '*');
  res.header('Access-Control-Allow-Methods', 'GET, OPTIONS');
  res.header('Access-Control-Allow-Headers', 'Content-Type, Authorization');
  next();
});

// Global error handling middleware
app.use((error, req, res, next) => {
  if (error instanceof SyntaxError && error.status === 400 && 'body' in error) {
    return res.status(400).json({ 
      error: 'Invalid JSON payload',
      message: 'Please check your request body format'
    });
  }
  next(error);
});

// Health check endpoint with input validation
app.get('/health', 
  [
    body('detailed').optional().isBoolean().withMessage('Detailed must be a boolean'),
  ],
  (req, res) => {
    try {
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({ 
          errors: errors.array(),
          message: 'Invalid query parameters'
        });
      }

      const { detailed = false } = req.query;
      const response = {
        status: 'ok',
        timestamp: new Date().toISOString(),
        uptime: process.uptime()
      };

      if (detailed) {
        response.memoryUsage = process.memoryUsage();
        response.env = process.env.NODE_ENV || 'development';
      }

      res.json(response);
    } catch (error) {
      console.error('Health check error:', error);
      res.status(500).json({ 
        error: 'Internal server error',
        message: 'Unable to complete health check'
      });
    }
  }
);

// Users endpoint with comprehensive validation and security
app.get('/users', 
  [
    body('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
    body('offset').optional().isInt({ min: 0 }).withMessage('Offset must be a positive integer'),
    body('search').optional().isLength({ max: 50 }).withMessage('Search term too long'),
  ],
  async (req, res) => {
    try {
      // Validate input
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({ 
          errors: errors.array(),
          message: 'Invalid query parameters'
        });
      }

      const { limit = 10, offset = 0, search = '' } = req.query;

      // Input sanitization
      const sanitizedSearch = search.toString().replace(/[^a-zA-Z0-9\s]/g, '');

      // Simulate database query with parameterized values
      // In production, use proper database connection with parameterized queries
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Filter based on search (simulated)
      const filteredUsers = users.filter(user => 
        user.name.toLowerCase().includes(sanitizedSearch.toLowerCase())
      );

      // Pagination
      const paginatedUsers = filteredUsers.slice(offset, offset + parseInt(limit));

      res.json({
        users: paginatedUsers,
        pagination: {
          total: filteredUsers.length,
          limit: parseInt(limit),
          offset: parseInt(offset),
          hasMore: offset + parseInt(limit) < filteredUsers.length
        }
      });

    } catch (error) {
      console.error('Users endpoint error:', error);
      res.status(500).json({ 
        error: 'Internal server error',
        message: 'Unable to retrieve users'
      });
    }
  }
);

// 404 handler
app.use('*', (req, res) => {
  res.status(404).json({ 
    error: 'Endpoint not found',
    message: `The requested endpoint ${req.originalUrl} does not exist`
  });
});

// Global error handler
app.use((error, req, res, next) => {
  console.error('Unhandled error:', error);

  // Don't leak error details in production
  const isProduction = process.env.NODE_ENV === 'production';

  res.status(500).json({
    error: 'Internal server error',
    message: isProduction ? 'Something went wrong' : error.message
  });
});

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Secure server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

module.exports = app;

