// Input validation middleware for Express.js
const { body, query, validationResult } = require('express-validator');

// Common validation rules
const commonValidations = {
  email: body('email').isEmail().normalizeEmail(),
  name: body('name').trim().isLength({ min: 2, max: 50 }).escape(),
  page: query('page').optional().isInt({ min: 1 }),
  limit: query('limit').optional().isInt({ min: 1, max: 100 })
};

// Validation middleware
const validate = (validations) => {
  return async (req, res, next) => {
    await Promise.all(validations.map(validation => validation.run(req)));

    const errors = validationResult(req);
    if (errors.isEmpty()) {
      return next();
    }

    res.status(400).json({
      error: 'Invalid input',
      details: errors.array()
    });
  };
};

// Sanitize input data
const sanitizeInput = (req, res, next) => {
  // Trim string fields
  if (req.body) {
    Object.keys(req.body).forEach(key => {
      if (typeof req.body[key] === 'string') {
        req.body[key] = req.body[key].trim();
      }
    });
  }

  if (req.query) {
    Object.keys(req.query).forEach(key => {
      if (typeof req.query[key] === 'string') {
        req.query[key] = req.query[key].trim();
      }
    });
  }

  next();
};

module.exports = {
  commonValidations,
  validate,
  sanitizeInput
};

// Comprehensive error handling middleware

class AppError extends Error {
  constructor(message, statusCode) {
    super(message);
    this.statusCode = statusCode;
    this.isOperational = true;

    Error.captureStackTrace(this, this.constructor);
  }
}

// Error types for better categorization
const errorTypes = {
  VALIDATION_ERROR: 'VALIDATION_ERROR',
  DATABASE_ERROR: 'DATABASE_ERROR',
  AUTHENTICATION_ERROR: 'AUTHENTICATION_ERROR',
  AUTHORIZATION_ERROR: 'AUTHORIZATION_ERROR',
  NOT_FOUND_ERROR: 'NOT_FOUND_ERROR',
  RATE_LIMIT_ERROR: 'RATE_LIMIT_ERROR',
  INTERNAL_ERROR: 'INTERNAL_ERROR'
};

// Error handler middleware
const errorHandler = (err, req, res, next) => {
  let error = { ...err };
  error.message = err.message;

  // Log error
  console.error('Error:', {
    message: err.message,
    stack: err.stack,
    url: req.originalUrl,
    method: req.method,
    ip: req.ip,
    timestamp: new Date().toISOString()
  });

  // Mongoose bad ObjectId
  if (err.name === 'CastError') {
    const message = 'Resource not found';
    error = new AppError(message, 404);
  }

  // Mongoose duplicate key
  if (err.code === 11000) {
    const message = 'Duplicate field value entered';
    error = new AppError(message, 400);
  }

  // Mongoose validation error
  if (err.name === 'ValidationError') {
    const message = Object.values(err.errors).map(val => val.message).join(', ');
    error = new AppError(message, 400);
  }

  // Default to 500 server error
  const statusCode = error.statusCode || 500;

  // Don't leak error details in production
  const response = process.env.NODE_ENV === 'production' 
    ? {
        error: 'Something went wrong',
        ...(statusCode === 500 ? {} : { message: error.message })
      }
    : {
        error: error.message,
        stack: error.stack,
        type: error.type
      };

  res.status(statusCode).json(response);
};

// Async error wrapper (eliminates need for try-catch blocks)
const catchAsync = (fn) => {
  return (req, res, next) => {
    fn(req, res, next).catch(next);
  };
};

// 404 handler
const notFound = (req, res, next) => {
  next(new AppError(`Not found - ${req.originalUrl}`, 404));
};

module.exports = {
  AppError,
  errorHandler,
  catchAsync,
  notFound,
  errorTypes
};

// Security configuration and middleware
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

// Security headers configuration
const securityHeaders = helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  frameguard: { action: 'deny' },
  noSniff: true,
  xssFilter: true,
  hsts: {
    maxAge: 31536000, // 1 year
    includeSubDomains: true,
    preload: true
  }
});

// Rate limiting configuration
const createRateLimiter = (windowMs, max, message) => {
  return rateLimit({
    windowMs,
    max,
    message: { error: message },
    standardHeaders: true,
    legacyHeaders: false,
    handler: (req, res) => {
      res.status(429).json({
        error: message,
        retryAfter: Math.ceil(windowMs / 1000)
      });
    }
  });
};

// Different rate limits for different endpoints
const generalRateLimit = createRateLimiter(
  15 * 60 * 1000, // 15 minutes
  100, // 100 requests
  'Too many requests, please try again later.'
);

const authRateLimit = createRateLimiter(
  15 * 60 * 1000, // 15 minutes
  5, // 5 login attempts
  'Too many authentication attempts, please try again later.'
);

const apiRateLimit = createRateLimiter(
  60 * 1000, // 1 minute
  30, // 30 API calls
  'API rate limit exceeded, please try again later.'
);

// Request size limits
const requestSizeLimit = (req, res, next) => {
  // Reject requests that are too large
  const contentLength = parseInt(req.headers['content-length'] || '0');
  if (contentLength > 10 * 1024) { // 10KB limit
    return res.status(413).json({
      error: 'Request too large',
      maxSize: '10KB'
    });
  }
  next();
};

// CORS configuration (simplified)
const corsOptions = {
  origin: function (origin, callback) {
    // Allow requests with no origin (like mobile apps or curl requests)
    if (!origin) return callback(null, true);

    // TODO: Configure allowed origins based on environment
    const allowedOrigins = [
      'http://localhost:3000',
      'http://localhost:3001'
    ];

    if (allowedOrigins.indexOf(origin) !== -1) {
