// Enhanced application with security best practices
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const { body, validationResult } = require('express-validator');

const app = express();

// 1. Security middleware
app.use(helmet()); // Sets various security headers

// 2. CORS configuration (restrict to trusted origins in production)
app.use(cors({
  origin: process.env.NODE_ENV === 'production' 
    ? ['https://yourdomain.com'] 
    : ['http://localhost:3000', 'http://localhost:3001'],
  credentials: true
}));

// 3. Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.'
  },
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// 4. Body parsing with limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// 5. Custom security middleware
app.use((req, res, next) => {
  // Remove sensitive headers
  res.removeHeader('X-Powered-By');

  // Set security headers
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');

  next();
});

// Global error handling middleware
app.use((error, req, res, next) => {
  console.error('Unhandled error:', error);

  // Don't leak error details in production
  if (process.env.NODE_ENV === 'production') {
    return res.status(500).json({
      error: 'Internal Server Error',
      message: 'Something went wrong. Please try again later.'
    });
  }

  res.status(500).json({
    error: error.name || 'Internal Server Error',
    message: error.message,
    stack: process.env.NODE_ENV === 'development' ? error.stack : undefined
  });
});

// Health endpoint with input validation
app.get('/health', [
  // Validate query parameters if any
], (req, res) => {
  try {
    // Validate input if there were any parameters
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({
        error: 'Validation failed',
        details: errors.array()
      });
    }

    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    console.error('Health endpoint error:', error);
    res.status(500).json({ 
      error: 'Internal server error',
      message: 'Failed to process health check'
    });
  }
});

// Users endpoint with proper validation and error handling
app.get('/users', [
  // Example validation for query parameters
  // body('page').optional().isInt({ min: 1 }).withMessage('Page must be a positive integer'),
  // body('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100')
], async (req, res) => {
  try {
    // Validate input
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({
        error: 'Validation failed',
        details: errors.array()
      });
    }

    // Simulate database query with proper error handling
    // In real application, this would be an async database call
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Sanitize output - remove sensitive data if needed
    const safeUsers = users.map(user => ({
      id: user.id,
      name: user.name,
      email: user.email
      // Don't include sensitive fields like password hashes
    }));

    res.json(safeUsers);

  } catch (error) {
    console.error('Users endpoint error:', error);

    // Don't expose database errors to client
    const errorMessage = process.env.NODE_ENV === 'development' 
      ? error.message 
      : 'Failed to retrieve users';

    res.status(500).json({
      error: 'Internal server error',
      message: errorMessage
    });
  }
});

// 404 handler - must be last
app.use('*', (req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Route ${req.originalUrl} not found`
  });
});

// Start server with proper error handling
const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Server running securely on port ${PORT}`);

  // Log security configuration
  console.log('Security features enabled:');
  console.log('- Helmet security headers');
  console.log('- Rate limiting (100 req/15min per IP)');
  console.log('- CORS protection');
  console.log('- Input validation');
  console.log('- Request size limits');
}).on('error', (error) => {
  console.error('Failed to start server:', error);
  process.exit(1);
});

module.exports = app;

