// Secure Express application with focus on error handling and input validation
const express = require('express');

const app = express();

// Security Middleware - Basic security headers
app.use((req, res, next) => {
  // Security headers
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');

  // Remove server identification
  res.removeHeader('X-Powered-By');

  next();
});

// Request size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Global error handling middleware
app.use((error, req, res, next) => {
  console.error('Application error:', error.name);

  res.status(500).json({
    error: 'Internal Server Error',
    message: 'An unexpected error occurred'
  });
});

// Health endpoint with improved error handling
app.get('/health', (req, res) => {
  try {
    // Input validation example
    if (req.query.detailed && req.query.detailed !== 'true' && req.query.detailed !== 'false') {
      return res.status(400).json({
        error: 'Validation Error',
        message: 'detailed parameter must be true or false'
      });
    }

    const response = { 
      status: 'ok', 
      timestamp: new Date().toISOString()
    };

    res.json(response);
  } catch (error) {
    console.error('Health endpoint error:', error);
    res.status(500).json({ 
      error: 'Internal server error',
      message: 'Health check failed'
    });
  }
});

// Users endpoint with enhanced input validation
app.get('/users', (req, res) => {
  try {
    // Input validation for query parameters
    const { limit, offset } = req.query;

    if (limit && !/^\d+$/.test(limit)) {
      return res.status(400).json({
        error: 'Validation Error',
        message: 'limit must be a positive integer'
      });
    }

    if (offset && !/^\d+$/.test(offset)) {
      return res.status(400).json({
        error: 'Validation Error',
        message: 'offset must be a positive integer'
      });
    }

    // Input sanitization - ensure numbers are safe
    const safeLimit = limit ? Math.min(parseInt(limit), 100) : 10; // Max 100 items
    const safeOffset = offset ? Math.max(0, parseInt(offset)) : 0;

    // Mock data response
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Return only the requested subset for pagination
    const response = users.slice(safeOffset, safeOffset + safeLimit);

    res.json({
      data: response,
      pagination: {
        limit: safeLimit,
        offset: safeOffset,
        total: users.length
      }
    });

  } catch (error) {
    console.error('Users endpoint error:', error);
    res.status(500).json({
      error: 'Internal server error',
      message: 'Failed to retrieve users'
    });
  }
});

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: 'Route not found'
  });
});

// Server startup with error handling
const PORT = 3000;

app.listen(PORT, () => {
  console.log('Server running on port 3000');
  console.log('Security features enabled:');
  console.log('- Basic security headers');
  console.log('- Input validation');
  console.log('- Error handling');
  console.log('- Request size limits');
}).on('error', (error) => {
  console.error('Server startup failed:', error.message);
});

module.exports = app;

