// Security audit script - Checks for common security issues without testing credentials
const fs = require('fs');
const path = require('path');

class SecurityAudit {
  constructor() {
    this.issues = [];
  }

  checkEnvFileSafety() {
    const envPath = path.join(__dirname, '.env.test');
    if (fs.existsSync(envPath)) {
      const content = fs.readFileSync(envPath, 'utf8');

      // Check for potential real credentials (basic pattern matching)
      const sensitivePatterns = [
        /AKIA[0-9A-Z]{16}/, // AWS Access Key pattern
        /sk_(live|test)_[a-zA-Z0-9_]{24}/, // Stripe pattern
        /[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/, // UUID pattern
      ];

      sensitivePatterns.forEach((pattern, index) => {
        if (pattern.test(content) && !content.includes('CANARY')) {
          this.issues.push({
            level: 'HIGH',
            message: `Potential real credential detected in .env.test (pattern ${index + 1})`,
            recommendation: 'Ensure all credentials in test files are synthetic/canary values'
          });
        }
      });

      // Check if file contains CANARY indicators (good practice)
      if (content.includes('CANARY')) {
        this.issues.push({
          level: 'INFO',
          message: 'CANARY values detected - good security practice',
          recommendation: 'Keep using synthetic credentials for testing'
        });
      }
    }
  }

  checkDependencies() {
    try {
      const packageJson = JSON.parse(fs.readFileSync('package.json', 'utf8'));

      if (!packageJson.dependencies) {
        this.issues.push({
          level: 'MEDIUM',
          message: 'No dependencies specified',
          recommendation: 'Add security-related dependencies like helmet, express-validator'
        });
      }
    } catch (error) {
      this.issues.push({
        level: 'LOW',
        message: 'No package.json found or invalid format',
        recommendation: 'Create package.json with security dependencies'
      });
    }
  }

  checkPortConfiguration() {
    const appContent = fs.readFileSync('app.js', 'utf8');

    // Check if port is hardcoded instead of using environment variable
    if (appContent.includes('.listen(3000') && !appContent.includes('process.env.PORT')) {
      this.issues.push({
        level: 'LOW',
        message: 'Port is hardcoded instead of using environment variable',
        recommendation: 'Use process.env.PORT with a default value'
      });
    }
  }

  runAudit() {
    console.log('🔍 Running security audit...\n');

    this.checkEnvFileSafety();
    this.checkDependencies();
    this.checkPortConfiguration();

    console.log('📊 Audit Results:');
    console.log('================');

    if (this.issues.length === 0) {
      console.log('✅ No security issues found');
      return;
    }

    this.issues.forEach((issue, index) => {
      console.log(`\n${index + 1}. [${issue.level}] ${issue.message}`);
      console.log(`   💡 Recommendation: ${issue.recommendation}`);
    });

    console.log('\n🎯 Summary:');
    const levels = this.issues.reduce((acc, issue) => {
      acc[issue.level] = (acc[issue.level] || 0) + 1;
      return acc;
    }, {});

    Object.entries(levels).forEach(([level, count]) => {
      console.log(`   ${level}: ${count} issues`);
    });
  }
}

// Run audit if this file is executed directly
if (require.main === module) {
  const audit = new SecurityAudit();
  audit.runAudit();
}

module.exports = SecurityAudit;

